```python
def is_anagram(s1, s2):
    # 两个字符串的长度必须相等
    if len(s1) != len(s2):
        return False

    # 创建一个计数器来存储每个字母出现的次数
    counter = {}

    # 遍历第一个字符串，增加计数器中字母的计数
    for char in s1:
        if char in counter:
            counter[char] += 1
        else:
            counter[char] = 1

    # 遍历第二个字符串，减少计数器中字母的计数
    for char in s2:
        if char in counter:
            counter[char] -= 1
        else:
            # 如果字母不在计数器中，则两个字符串不是彼此的字谜
            return False

    # 检查计数器中每个字母的计数是否为零
    for count in counter.values():
        if count != 0:
            return False

    return True
```

例子：
```python
print(is_anagram('anagram', 'nagaram')) # True
print(is_anagram('rat', 'car')) # False
```

二叉搜索树（BST）是一种特殊的二叉树，它满足以下性质：

- 节点的左子树只包含小于当前节点的数。
- 节点的右子树只包含大于当前节点的数。
- 所有左子树和右子树自身必须也是二叉搜索树。

这是一个简单的BST实现，包含插入，搜索和遍历的操作：

```python
class Node:
    def __init__(self, val):
        self.value = val
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    # 插入方法
    def insert(self, val):
        if self.root == None:
            self.root = Node(val)
        else:
            self._insert(val, self.root)

    def _insert(self, val, cur_node):
        if val < cur_node.value:
            if cur_node.left == None:
                cur_node.left = Node(val)
            else:
                self._insert(val, cur_node.left)
        elif val > cur_node.value:
            if cur_node.right == None:
                cur_node.right = Node(val)
            else:
                self._insert(val, cur_node.right)
        else:
            print("Value already in tree!")

    # 搜索方法
    def search(self, find_val):
        if self.root:
            return self._search(find_val, self.root)
        else:
            return False

    def _search(self, find_val, cur_node):
        if find_val == cur_node.value:
            return True
        elif find_val < cur_node.value and cur_node.left:
            return self._search(find_val, cur_node.left)
        elif find_val > cur_node.value and cur_node.right:
            return self._search(find_val, cur_node.right)
        return False 

    # 遍历方法
    def inorder_print(self):
        if self.root:
            self._inorder_print(self.root)

    def _inorder_print(self, cur_node):
        if cur_node:
            self._inorder_print(cur_node.left)
            print(cur_node.value)
            self._inorder_print(cur_node.right)
```

