```python
def bubble_sort(arr):
    n = len(arr)

    # 遍历所有数组元素
    for i in range(n):

        # 最后的 i 个元素已经到位
        for j in range(0, n-i-1):

            # 如果当前元素大于下一个元素，交换位置
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]

    return arr
```

此代码段实现了冒泡排序算法，它通过重复遍历整个数组，比较相邻的元素并交换位置，最终使数组中的元素按从小到大的顺序排列。它的时间复杂度为 O(n^2)，是一种简单但效率不高的排序方法。

下面是一个基本的链表C++库示例，它具有常见的链表操作，例如添加节点，删除节点，遍历列表等。

```c++
#include <iostream>
using namespace std;

// 定义链表节点的结构体
struct Node{
    int data; // 节点的数据
    Node *next; // 节点的指针
};

// 链表类
class LinkedList{
private:
    Node *head; // 链表的头指针
public:
    // 构造函数
    LinkedList(){
        head = nullptr;
    }

    // 向链表中添加新节点，节点数据为val
    void addNode(int val){
        Node *newNode = new Node();
        newNode->data = val;
        newNode->next = nullptr;

        // 如果链表为空，则新节点设置为头节点
        if(head == nullptr){
            head = newNode;
            return;
        }

        // 否则将新节点添加到链表尾部
        Node *tmp = head;
        while(tmp->next != nullptr){
            tmp = tmp->next;
        }
        tmp->next = newNode;
    }

    // 删除链表中第一个值为val的节点
    void deleteNode(int val){
        Node *tmp = head;
        Node *prev = nullptr;

        // 遍历链表，找到值为val的节点
        while(tmp != nullptr && tmp->data != val){
            prev = tmp;
            tmp = tmp->next;
        }

        // 如果链表中存在值为val的节点
        if(tmp != nullptr){
            // 如果要删除的节点是头节点
            if(tmp == head){
                head = tmp->next;
            }else{ // 删除中间或尾节点
                prev->next = tmp->next;
            }
            // 释放内存
            delete tmp;
        }
    }

    // 遍历链表并打印节点数据
    void display(){
        Node *tmp = head;
        while(tmp != nullptr){
            cout << tmp->data << " ";
            tmp = tmp->next;
        }
        cout << endl;
    }

    // 析构函数，释放链表占用的内存

