```

这是一个简单的C++程序，找到给定数组的最小值和最大值：

```cpp
#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "请输入数组大小：" << endl;
    cin >> n;
    int arr[n]; 
    cout << "请输入数组元素：" << endl;
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }
    int max=arr[0];
    int min=arr[0];
    for (int i = 0; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        } else if (arr[i] < min) {
            min = arr[i];
        }
    }
    cout << "数组的最大值为： " << max << endl;
    cout << "数组的最小值为： " << min << endl;
    return 0;
}
```
执行此程序时，它将提示您输入数组的大小和元素。 然后，程序将打印给定数组的最大和最小值。

