这是一个Python程序，可以接受0到9999之间的数字，并打印出数字的口语化版本：

```python
def to_word(num):
    word_dict = {0: 'zero', 1: 'one', 2: 'two', 3: 'three', 4: 'four', 5: 'five', 
                 6: 'six', 7: 'seven', 8: 'eight', 9: 'nine', 10: 'ten',
                 11: 'eleven', 12: 'twelve', 13: 'thirteen', 14: 'fourteen', 15: 'fifteen', 
                 16: 'sixteen', 17: 'seventeen', 18: 'eighteen', 19: 'nineteen', 20: 'twenty',
                 30: 'thirty', 40: 'forty', 50: 'fifty', 60: 'sixty', 70: 'seventy',
                 80: 'eighty', 90: 'ninety', 100: 'hundred', 1000: 'thousand'}

    if num in word_dict:
        return word_dict[num]
    else:
        result = []
        if num >= 1000:
            result.append(word_dict[num//1000])
            result.append('thousand')
            num = num % 1000
        if num >= 100:
            result.append(word_dict[num//100])
            result.append('hundred')
            num = num % 100
        if num >= 20:
            result.append(word_dict[num//10*10])
            num = num % 10
        if num > 0:
            result.append(word_dict[num])
        return ' '.join(result)

num = int(input("请输入一个0到9,999之间的数字: "))
if num >=0 and num<=9999:
    print(to_word(num))
else:
    print("输入错误")
```

