int findMax(int arr[], int n)
{
   int max = arr[0]; // 假设最大数是第一个数

   // 迭代数组中的所有元素来找到最大值
   for (int i = 1; i < n; i++)
   {
      // 比较当前元素和 max 的值
      if (arr[i] > max)
      {
         max = arr[i];
      }
   }

   return max;
}
