def next_multiple_of_three(n: int) -> int:
    """
    :param n: An integer as the input
    :return: If the input is greater than 4 it returns 0. If the input is not divisible by 3, it returns the next multiple of 3.
    """
    if n > 4:
        return 0
    elif n % 3 != 0:
        return n + (3 - n % 3)
    else:
        return n

