```
import calendar
from datetime import datetime, timedelta

class MyCalendar:
    def __init__(self):
        self.events = {}

    def add_event(self, date, event_name):
        """添加事件到指定日期"""
        if date in self.events:
            self.events[date].append(event_name)
        else:
            self.events[date] = [event_name]

    def remove_event(self, date, event_name):
        """从指定日期移除事件"""
        if date in self.events and event_name in self.events[date]:
            self.events[date].remove(event_name)

    def view_events(self, date=None):
        """查看指定日期的事件，如果没有提供日期，则查看所有事件"""
        if date:
            if date in self.events:
                print(f"Events on {date}:")
                for event in self.events[date]:
                    print(f"- {event}")
            else:
                print(f"There are no events on {date}.")
        else:
            print("All events:")
            for date in self.events:
                print(f"{date}:")
                for event in self.events[date]:
                    print(f"- {event}")

    def view_month(self, year, month):
        """查看指定月份的日历和事件"""
        cal = calendar.month(year, month)
        print(cal)
        for date in range(1, calendar.monthrange(year, month)[1]+1):
            date_str = f"{year}-{month:02}-{date:02}"
            if date_str in self.events:
                print(f"{date_str}:")
                for event in self.events[date_str]:
                    print(f"- {event}")

    def set_reminder(self, date, event_name, days_before):
        """在事件发生前的指定天数设定提醒"""
        reminder_date = datetime.strptime(date, "%Y-%m-%d") - timedelta(days=days_before)
        reminder_date_str = reminder_date.strftime("%Y-%m-%d")
        reminder_text = f"Reminder: {event_name} on {date}"
        self.add_event(reminder_date_str, reminder_text)

