下面是一个使用回溯法的 Python 算法，可以解决标准的 9x9 数独谜题。

```python
import numpy as np

def sudoku_solver(board):
    find_empty = empty_pos(board)
    if not find_empty:
        return True
    else:
        row, col = find_empty

    for i in range(1, 10):
        if is_valid(board, i, (row, col)):
            board[row][col] = i

            if sudoku_solver(board):
                return True

            board[row][col] = 0

    return False


def is_valid(board, number, position):

    for i in range(len(board[0])):
        if board[position[0]][i] == number and position[1] != i:
            return False

    for i in range(len(board)):
        if board[i][position[1]] == number and position[0] != i:
            return False

    box_x = position[1] // 3
    box_y = position[0] // 3

    for i in range(box_y*3, box_y*3 + 3):
        for j in range(box_x*3, box_x*3 + 3):
            if board[i][j] == number and (i,j) != position:
                return False

    return True


def print_board(board):
    for i in range(len(board)):
        if i % 3 == 0 and i != 0:
            print("- - - - - - - - - - - - ")
        for j in range(len(board[0])):
            if j % 3 == 0 and j != 0:
                print("| ", end="")
            if j == 8:
                print(board[i][j])
            else:
                print(str(board[i][j]) + " ",end="")

def empty_pos(board):
    for i in range(len(board)):
        for j in range(len(board[0])):
            if board[i][j] == 0:
                return (i, j)  # row, col

    return None


