def prime_number():
    """用简单的筛法找出0到100之间的所有质数"""
    primes = []
    for i in range(2, 101):
        isPrime = True
        for j in range(2, i):
            if i % j == 0:
                isPrime = False
                break
        if isPrime:
            primes.append(i)
    return primes


