算法: 使用汉明距离(编辑距离）衡量两个字符串之间的相似度

首先我们可以对输入的字符串进行简单的预处理,将其中的逗号去掉，然后保证各个字符串仅保留单个空格。

def levenshtein_distance(string1, string2):

    size1 = len(string1) + 1
    size2 = len(string2) + 1
    matrix = [[0] * size2 for i in range(size1)]

    for x in range(size1):
        matrix [x][0] = x
    for y in range (size2):
        matrix [0][y] = y

    for x in range(1, size1):
        for y in range(1, size2):
            if string1[x-1] == string2[y-1]:
                matrix [x][y] = min(
                    matrix[x-1][y] + 1,
                    matrix[x-1][y-1],
                    matrix[x][y-1] + 1
                )
            else:
                matrix [x][y] = min(
                    matrix[x-1][y] + 1,
                    matrix[x-1][y-1] + 1,
                    matrix[x][y-1] + 1
                )

    return matrix[size1 - 1][size2 - 1]

string1 = "背包面料"
string2 = "面料包"

distance = levenshtein_distance(string1, string2)

print(distance)

