输出: [0, 1, 3, 4, 7, 8, 9]

算法：使用快速排序算法进行排序

void quicksort(int arr[], int low, int high){
    if(low < high){
        int pivot_index = partition(arr, low, high); // 划分数组并返回枢轴
        quicksort(arr, low, pivot_index - 1); // 递归排序左边的子数组
        quicksort(arr, pivot_index + 1, high); // 递归排序右边的子数组
    }
}

int partition(int arr[], int low, int high){
    int pivot = arr[high]; // 选择最后一个元素作为枢轴
    int i = low -1; // 用来追踪比枢轴小的元素的位置
    for(int j = low; j <= high - 1; j++){
       // 如果当前元素 <= pivot，就将它移动到比枢轴小的位置
        if(arr[j] <= pivot){
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

void swap(int* a, int* b){
    int temp = *a;
    *a = *b;
    *b = temp;
}

为了使用上面的函数，可以这样调用：

int arr[] = {3, 7, 1, 0, 4, 9, 8};
int n = sizeof(arr)/sizeof(arr[0]);
quicksort(arr, 0, n-1);

