下面是一个C语言程序，它使用了数学公式来求解二次方程（ax²+bx+c=0）。
```c
#include <stdio.h>
#include <math.h>

int main()
{
    double a, b, c, discriminant, root1, root2, realPart, imaginaryPart;

    printf("Enter coefficients a, b and c: ");
    scanf("%lf %lf %lf",&a, &b, &c);

    discriminant = b * b - 4 * a * c;

    //判断根的类型
    if (discriminant > 0)
    {
        root1 = (-b + sqrt(discriminant)) / (2 * a);
        root2 = (-b - sqrt(discriminant)) / (2 * a);
        printf("root1 = %.2lf and root2 = %.2lf", root1, root2);
    }
    else if (discriminant == 0)
    {
        root1 = root2 = -b / (2 * a);
        printf("root1 = root2 = %.2lf;", root1);
    }
    else
    {
        realPart = -b / (2 * a);
        imaginaryPart = sqrt(-discriminant) / (2 * a);
        printf("root1 = %.2lf+%.2lfi and root2 = %.2lf-%.2lfi", realPart, imaginaryPart, realPart, imaginaryPart);
    }
    return 0;
}
```
该程序要求用户输入二次方程的系数a，b和c，然后计算出方程的根。它首先计算判别式的值，然后根据判别式的值判断根的类型。如果判别式为正，则方程有两个实根；如果判别式为0，则方程有一个实根；否则，方程有两个复根。最后，根据公式计算出方程的根并输出。
